window.LYRICS=[{"s":3.431,"e":3.431,"t":"[Intro]"},{"s":3.431,"e":9.096,"t":"(Female) Канамэ Датэ. Левый глаз отсутствует."},{"s":9.096,"e":14.202,"t":"Вживлена ИИ-партнёр Айба."},{"s":14.202,"e":24.202,"t":"(Male) Очередной труп. Очередной сон. Поехали."},{"s":37.58,"e":37.58,"t":"[Verse 1 - Male]"},{"s":37.58,"e":40.532,"t":"Токио ночью, кровь на плитке, тело без ответа,"},{"s":40.532,"e":44.202,"t":"Я детектив ABIS — лезу не в улики, а в чужие сны."},{"s":44.202,"e":48.67,"t":"Шесть минут в Сомниуме: двери, замки, чужой кошмар,"},{"s":48.67,"e":52.5,"t":"Если не успеешь — проснёшься, и дело сгниёт вместе с тобой."},{"s":52.5,"e":56.809,"t":"Псинк-машина гудит, кабель в затылок, реальность плывёт,"},{"s":56.809,"e":60.239,"t":"Чтобы поймать убийцу, надо понять, чего боится его мозг."},{"s":60.239,"e":63.59,"t":"Не отпечатки, не пуля — страх, ложь и детская травма,"},{"s":63.59,"e":72.367,"t":"Правда живёт там, где человек себе врёт каждый день."},{"s":72.367,"e":72.367,"t":"[Pre-Chorus - Female]"},{"s":72.367,"e":77.314,"t":"Я Айба. Я твой глаз, твой рот и твоя совесть."},{"s":77.314,"e":83.218,"t":"Не пялься на девушек. Смотри на улики."},{"s":83.218,"e":88.165,"t":"У тебя шесть минут. Не облажайся, Датэ-сан."},{"s":88.165,"e":88.165,"t":"[Chorus - Both + Choir]"},{"s":88.165,"e":91.995,"t":"SOMNUS FILES! Ныряем в сон, вытаскиваем правду!"},{"s":91.995,"e":99.415,"t":"SOMNUS FILES! Каждый кошмар — это место преступления!"},{"s":99.415,"e":102.686,"t":"Замок в голове, таймер на нуле, сигарета в зубах,"},{"s":102.686,"e":110.346,"t":"Детектив и искусственный глаз против целого ада!"},{"s":110.346,"e":110.346,"t":"[Verse 2 - Male]"},{"s":110.346,"e":113.537,"t":"Мизуки орёт, что я никуда не гожусь, и в чём-то права,"},{"s":113.537,"e":117.207,"t":"Айрис поёт про инопланетян, Босс кидает папки в лицо."},{"s":117.207,"e":120.08,"t":"Подозреваемый улыбается днём и режет ночью,"},{"s":120.08,"e":122.394,"t":"А я шучу пошло, потому что иначе с ума сойду."},{"s":122.394,"e":125.505,"t":"В чужом сне лестница ведёт в никуда, часы идут назад,"},{"s":125.505,"e":128.218,"t":"Кукла говорит правду, а мать убитого молчит."},{"s":128.218,"e":131.25,"t":"Нажимаю на болевую точку — ментальный замок падает,"},{"s":131.25,"e":134.282,"t":"И всплывает то, что человек прятал даже от себя."},{"s":134.282,"e":134.282,"t":"[Verse 3 - Female]"},{"s":134.282,"e":140.186,"t":"Он вечно опаздывает, вечно в долгах, вечно в дыму,"},{"s":140.186,"e":146.17,"t":"Но когда таймер пищит — этот идиот не сдаётся."},{"s":146.17,"e":151.277,"t":"Я считаю вероятности, он идёт напролом,"},{"s":151.277,"e":157.739,"t":"Вместе мы хуже по отдельности. Вместе мы опасны."},{"s":157.739,"e":157.739,"t":"[Bridge - Both]"},{"s":157.739,"e":159.654,"t":"(Male) Если правда спрятана во сне…"},{"s":159.654,"e":162.846,"t":"(Female) Тогда мы взломаем этот сон."},{"s":162.846,"e":165.239,"t":"(Male) Если убийца внутри головы…"},{"s":165.239,"e":169.707,"t":"(Female) Тогда добро пожаловать в Сомниум."},{"s":169.707,"e":169.707,"t":"[Final Chorus - Both + Choir]"},{"s":169.707,"e":175.372,"t":"SOMNUS FILES! Шесть минут до конца чужого разума!"},{"s":175.372,"e":179.601,"t":"SOMNUS FILES! Мы читаем ложь, пока она ещё дышит!"},{"s":179.601,"e":184.149,"t":"Псинк, кровь, неон, сирена, глаз в темноте,"},{"s":184.149,"e":193.404,"t":"Пока Айба со мной — это дело не закроют без нас!"},{"s":193.404,"e":193.404,"t":"[Outro]"},{"s":193.404,"e":203.404,"t":"(Female) Psync complete. Данные сохранены."},{"s":203.457,"e":205.851,"t":"(Male) Хорошо."},{"s":205.851,"e":211.926,"t":"Кто следующий ляжет на стол?"}];
